m1-day8.code:
raw = ['Ari|FAIL', 'Bo|OK', 'Ari|failure']
aliases = {'FAIL': 'fail', 'failure': 'fail', 'OK': 'ok'}
records = []
for line in raw:
    user, status = line.split('|')
    records.append({'user': user, 'status': aliases[status]})
failures = 0
for record in records:
    if record['status'] == 'fail':
        failures += 1
print(f'failures={failures}')
